"""Lecture rythmique : valeurs variées, notations et entraînement progressif."""
import json

VALUES={'w':48,'h':24,'q':12,'e':6,'s':3}
def n(value,rest=False,dots=0,tie=False,tuplet=None):
    ticks=VALUES[value]*(1.5 if dots else 1)
    if tuplet:ticks=VALUES[value]*2/3
    return {'value':value,'ticks':int(ticks),'rest':rest,'dots':dots,'tieNext':tie,'tuplet':tuplet}
def pattern(name,events,meter='4/4',description='',swing=False):
    bar_ticks=48 if meter=='4/4' else 36
    pulse_ticks=18 if meter=='6/8' else 12
    total=sum(e['ticks'] for e in events)
    if total%bar_ticks:raise ValueError(name+': mesure incomplète')
    return {'name':name,'meter':meter,'barTicks':bar_ticks,'pulseTicks':pulse_ticks,'pulses':bar_ticks//pulse_ticks,'bars':total//bar_ticks,'events':events,'description':description,'swing':swing}
def rhythm_patterns():
    result={
    'whole':pattern('01 · Une ronde',[n('w')],description='Une attaque, un son tenu pendant quatre temps.'),
    'halves':pattern('02 · Deux blanches',[n('h'),n('h')],description='Deux attaques : sur les temps 1 et 3.'),
    'quarters':pattern('03 · Quatre noires',[n('q') for _ in range(4)],description='Une attaque sur chacun des quatre temps.'),
    'eighths':pattern('04 · Croches et blanche',[n('e') for _ in range(4)]+[n('h')],description='Quatre croches sur les deux premiers temps ; une blanche sur les deux derniers.'),
    'dotted-half':pattern('05a · Blanche pointée et noire',[n('h',dots=1),n('q')],description='La blanche pointée dure trois temps ; la noire arrive sur 4.'),
    'dotted-quarter':pattern('05b · Noire pointée et croche',[n('q',dots=1),n('e'),n('q'),n('q')],description='1½ + ½ + 1 + 1 temps. La croche arrive sur le « et » de 2.'),
    'rests':pattern('06a · Silence, noire et demi-pause',[n('q',rest=True),n('q'),n('h',rest=True)],description='Silence sur 1 ; noire sur 2 ; deux temps de silence sur 3 et 4.'),
    'eighth-rests':pattern('06b · Demi-soupirs et croches',[n('q',rest=True),n('e'),n('e',rest=True),n('q'),n('q',rest=True)],description='Le souffle s’interrompt sur les silences, mais le comptage continue.'),
    'whole-rest':pattern('06c · Une pause de quatre temps',[n('w',rest=True)],description='Une mesure entière de silence compté.'),
    'sixteenths':pattern('07a · Doubles croches et valeurs mixtes',[n('q')]+[n('s') for _ in range(4)]+[n('e'),n('e'),n('q')],description='Quatre doubles croches occupent le temps 2.'),
    'sixteenth-rests':pattern('07b · Quart de soupir',[n('e'),n('s',rest=True),n('s'),n('q'),n('h')],description='Une croche, un silence de double croche, puis une double croche sur la dernière subdivision du temps 1.'),
    'dotted-eighths':pattern('08 · Croches pointées et doubles croches',sum(([n('e',dots=1),n('s')] for _ in range(4)),[]),description='Chaque paire dure un temps : ¾ + ¼. Ce rapport 3:1 diffère du modèle swing 2:1.'),
    'untied':pattern('09a · Notes séparées',[n('e'),n('e'),n('q'),n('q'),n('q')],description='Cinq attaques : aucune note n’est liée.'),
    'ties':pattern('09b · Croche liée à une noire',[n('e'),n('e',tie=True),n('q'),n('q'),n('q')],description='La deuxième croche prolonge son son sur la noire suivante : quatre attaques au lieu de cinq.'),
    'triplets':pattern('10a · Triolets de croches',[n('e',tuplet='t1') for _ in range(3)]+[n('q'),n('e'),n('e'),n('q')],description='Trois croches en triolet occupent le seul temps 1.'),
    'quarter-triplets':pattern('10b · Triolets de noires',[n('q',tuplet='t1') for _ in range(3)]+[n('q',tuplet='t2') for _ in range(3)],description='Chaque groupe de trois noires occupe deux temps : six attaques sur quatre temps.'),
    'crossbar':pattern('11 · Liaison à travers la barre de mesure',[n('q'),n('e'),n('e'),n('q'),n('q',tie=True),n('q'),n('e',rest=True),n('e'),n('e',dots=1),n('s'),n('q')],description='Deux mesures. Le son commencé sur 4 traverse le temps 1 suivant sans nouvelle attaque.'),
    'waltz':pattern('12a · Trois temps en 3/4',[n('h'),n('q')],meter='3/4',description='Une blanche puis une noire : trois pulsations à la noire.'),
    'compound':pattern('12b · Deux temps composés en 6/8',[n('e'),n('e'),n('e'),n('q',dots=1)],meter='6/8',description='Trois croches puis une noire pointée : deux pulsations à la noire pointée.'),
    }
    swing_events=sum(([{**n('e'),'ticks':8},{**n('e'),'ticks':4}] for _ in range(4)),[])
    result['swing']=pattern('Comparer · Croches swing, modèle 2:1',swing_events,description='Huit croches interprétées avec une longue et une courte par temps. Modèle pédagogique : ⅔ + ⅓.',swing=True)
    return result

def build_rhythm_course(env):
    table,call,sec,ex,page=[env[k] for k in ('table','call','sec','exercise','render_page')]
    from listening_workshops import preferences
    out=env['OUT'];patterns=rhythm_patterns()
    (out/'assets/rhythms.js').write_text('/* Valeurs de lecture rythmique, sans dépendance réseau. */\nwindow.JAZZ_RHYTHMS='+json.dumps(patterns,ensure_ascii=False,separators=(',',':'))+';\n')
    options=''.join(f'<option value="{key}">{p["name"]}</option>' for key,p in patterns.items())
    tool='''<div class="tool"><p class="eyebrow">Lire · compter · écouter · jouer</p><div class="controls"><label for="rhythm-pattern">Exemple <select id="rhythm-pattern">'''+options+'''</select></label></div><div class="controls"><label for="tempo">Tempo <span id="tempo-unit">♩ =</span> <output id="tempo-value" for="tempo">60</output><input id="tempo" type="range" min="40" max="140" value="60" step="2" aria-label="Pulsations par minute"></label><label for="metro-mode">Clic <select id="metro-mode"><option value="all">Chaque pulsation</option><option value="24">Sur 2 et 4 en 4/4</option><option value="none">Décompte seul</option></select></label></div><p class="mini" id="rhythm-description"></p><div class="beat-lights" id="rhythm-beats" aria-label="Pulsations de la mesure"></div><div class="diagram-scroll" id="rhythm-drawing"></div><p id="attack-count" class="mini"></p><button class="btn primary" id="rhythm-start" aria-pressed="false">Écouter en boucle</button><p class="player-status" id="rhythm-status" aria-live="polite">Une mesure de décompte précède l’exemple. Le son est joué sur une seule hauteur ; concentrez-vous sur les durées.</p><noscript>Le tableau des valeurs, les comptages et les corrections permettent de travailler sans le lecteur.</noscript></div>'''
    def score(key):return '<figure class="rhythm-example"><div class="diagram-scroll" data-rhythm-score="'+key+'"></div><figcaption>'+patterns[key]['description']+'</figcaption></figure>'
    def exercise(number,title,objective,prereq,statement,deliverable,criteria,hints,correction,key):
        html=ex('10.'+str(number),title,objective,prereq,statement,deliverable,criteria,hints,correction)
        return html.replace('</h3>','</h3>'+score(key),1)
    exercises=[
    exercise(1,'Tenir une ronde','Soutenir le son et compter quatre temps.','La pulsation.','À 60 à la noire, jouez une ronde sur une note confortable. Comptez 1–2–3–4 sans réattaquer. Reprenez quatre fois.','Quatre mesures avec une attaque chacune.','Chaque son occupe quatre temps et la mesure suivante commence sans accélération.',('Une ronde vaut quatre noires.','La langue ne relance pas les temps 2, 3 et 4.'),'Une attaque au temps 1, puis une tenue jusqu’à la fin du temps 4. Quatre mesures donnent quatre attaques.','whole'),
    exercise(2,'Passer de la ronde aux blanches','Partager la mesure en deux.','Ronde et pulsation.','Alternez une mesure en ronde et une mesure avec deux blanches. Gardez quatre temps par mesure.','Quatre paires de mesures.','Les blanches commencent sur 1 et 3 ; la ronde ne change pas de tempo.',('Une blanche dure deux temps.','Comptez 1–2 pour la première, 3–4 pour la seconde.'),'Les deux blanches totalisent 2 + 2 = 4 temps. Une paire ronde / blanches comporte trois attaques sur huit temps.','halves'),
    exercise(3,'Quatre noires régulières','Articuler sans modifier la pulsation.','Blanches.','Jouez quatre noires par mesure, puis revenez aux blanches. Répétez à 50, puis 60.','Deux séries de quatre mesures.','Chaque noire commence sur une pulsation ; les blanches durent toujours deux pulsations.',('Le tempo ne change pas lorsque les notes deviennent plus courtes.','Quatre noires et deux blanches ont la même durée totale.'),'Les attaques des noires sont sur 1, 2, 3 et 4. Modifier la valeur des notes change leur durée, pas la vitesse de la pulsation.','quarters'),
    exercise(4,'Croches et blanche dans une même mesure','Diviser un temps en deux et prolonger ensuite.','Noires et blanches.','Comptez « 1 et 2 et 3 et 4 et ». Jouez quatre croches sur les temps 1 et 2, puis une blanche sur 3 et 4.','Quatre mesures identiques.','Les croches sont égales ; la blanche ne reçoit pas de nouvelle attaque sur 4.',('Chaque croche vaut un demi-temps.','La dernière attaque arrive sur 3.'),'Quatre croches occupent deux temps ; la blanche en occupe deux autres. Les cinq attaques tombent à 0, ½, 1, 1½ et 2 temps depuis le début de la mesure.','eighths'),
    exercise(5,'Lire les valeurs pointées','Ajouter la moitié de la durée d’origine.','Croches et blanches.','Jouez d’abord blanche pointée + noire, puis noire pointée + croche + deux noires. Dites le comptage avant de jouer.','Deux mesures différentes, répétées quatre fois.','La blanche pointée dure trois temps ; la noire pointée dure 1½ temps.',('Un point ajoute la moitié de la valeur de départ.','1½ + ½ + 1 + 1 = 4.'),'La première mesure attaque sur 1 et 4. Dans la seconde : 1, « et » de 2, 3 et 4. La croche n’arrive pas sur 2, mais une demi-pulsation après.','dotted-quarter'),
    exercise(6,'Compter les silences','Conserver le temps quand le son s’arrête.','Noires, blanches et croches.','Jouez soupir, noire, demi-pause ; puis l’exemple de croches et demi-soupirs. Le souffle s’arrête pendant les silences, le pied continue.','Deux mesures différentes à quatre temps.','La première n’a qu’une attaque, sur 2 ; les silences ne raccourcissent pas la mesure.',('Un soupir dure une noire ; une demi-pause, deux noires.','Le silence est une durée écrite, pas une durée libre.'),'Première mesure : 1 temps de silence + 1 temps de note + 2 temps de silence. Dans l’exemple de demi-soupirs, les attaques sont sur 2 puis 3 ; une demi-pulsation de silence suit la croche du temps 2.','rests'),
    exercise(7,'Installer les doubles croches','Diviser un temps en quatre.','Croches égales.','Jouez noire, quatre doubles croches, deux croches, noire. Comptez quatre petites subdivisions sur le temps 2. Essayez ensuite la variante avec quart de soupir.','Quatre mesures de l’exemple, puis quatre de la variante.','Les quatre doubles croches occupent exactement le temps 2.',('Une double croche vaut un quart de temps.','Dites « 2-e-et-a » pour les quatre départs du temps 2.'),'1 + 4×¼ + 2×½ + 1 = 4 temps. La variante commence par une croche, un silence de ¼ de temps puis une double croche, soit un temps complet.','sixteenths'),
    exercise(8,'Croche pointée et double croche','Lire le rapport 3:1.','Doubles croches et point.','Répétez quatre fois la paire croche pointée / double croche dans une mesure. Gardez quatre petites unités égales par temps.','Quatre mesures sans dérive.','La première note dure trois petites unités ; la seconde une seule.',('La croche pointée dure ¾ de temps.','Le rapport est 3:1, pas le modèle swing 2:1.'),'Chaque paire fait ¾ + ¼ = 1 temps. Les départs sont 1, « a » de 1, 2, « a » de 2, 3, « a » de 3, 4, « a » de 4.','dotted-eighths'),
    exercise(9,'Comparer notes liées et séparées','Reconnaître une liaison de prolongation.','Croches et noires.','Comparez les exemples 09a et 09b. Dans le second, la deuxième croche est liée à la noire suivante. Ne réattaquez pas cette noire.','Deux mesures séparées puis deux mesures liées.','La version séparée comporte cinq attaques ; la version liée quatre.',('La durée des deux notes liées s’additionne.','La hauteur ne change pas : il s’agit d’une prolongation.'),'La liaison réunit ½ + 1 = 1½ temps. Elle supprime l’attaque sur le temps 2, sans supprimer ce temps du comptage. C’est une syncope : le son parti sur le « et » de 1 traverse le temps 2.','ties'),
    exercise(10,'Distinguer deux sortes de triolets','Passer du binaire au ternaire avec une pulsation stable.','Croches et noires.','Jouez l’exemple avec trois croches en triolet sur le temps 1 ; comparez ensuite les deux groupes de triolets de noires.','Deux mesures de chaque exemple.','Le triolet de croches dure un temps ; le triolet de noires deux temps.',('Le chiffre 3 s’applique au groupe indiqué.','Trois croches en triolet : ⅓ de temps chacune ; trois noires en triolet : ⅔ chacune.'),'Le premier exemple comporte sept attaques : trois sur le temps 1, une sur 2, deux sur 3 et une sur 4. Les deux groupes de triolets de noires donnent six attaques réparties sur quatre temps.','triplets'),
    exercise(11,'Traverser la barre de mesure','Maintenir une liaison et retrouver les appuis.','Liaisons, silences, valeurs pointées et doubles croches.','Jouez les deux mesures de l’exemple. La dernière noire de la première est liée à la première noire de la seconde. Comptez le nouveau temps 1 sans l’attaquer.','Deux mesures répétées quatre fois, clic sur chaque temps puis sur 2 et 4.','La liaison dure deux temps ; le demi-soupir de la seconde mesure reste audible comme absence de son.',('La barre de mesure ne coupe pas un son lié.','L’attaque du temps 4 de la première mesure dure jusqu’au temps 2 de la suivante.'),'Le groupe lié commence à 3 temps depuis le début de la première mesure et se termine à 5. Le temps 1 suivant n’a pas de nouvelle attaque ; le temps 2 commence par un demi-soupir. Les deux mesures comportent neuf attaques.','crossbar'),
    exercise(12,'Comparer 3/4 et 6/8','Entendre le regroupement des pulsations.','Blanches, croches et valeurs pointées.','Jouez blanche + noire en 3/4 avec trois pulsations à la noire. Passez ensuite à trois croches + noire pointée en 6/8 avec deux pulsations à la noire pointée.','Quatre mesures dans chaque chiffrage.','Vous annoncez trois pulsations en 3/4 et deux en 6/8 ; le tempo est rapporté à la bonne figure.',('Les deux mesures contiennent l’équivalent de trois noires, mais leur regroupement diffère.','En 6/8, comptez « 1-la-li 2-la-li ».'),'En 3/4, la blanche occupe les pulsations 1 et 2 ; la noire occupe 3. En 6/8, les trois croches divisent la première pulsation, la noire pointée remplit la seconde. À la même valeur numérique de tempo, les deux mesures n’ont pas la même durée en secondes.','compound'),
    exercise(13,'Composer une phrase de quatre mesures','Réunir lecture rythmique et notes cibles.','Les douze étapes précédentes et II–V–I.','En 4/4, sur | Fm7 | B♭7 | E♭maj7 | E♭maj7 | écrits pour ténor, choisissez un rythme différent par mesure. Incluez une valeur pointée, une liaison et au moins deux temps de silence. Restez sur La♭, La♭, Sol, Sol pour concentrer le travail sur les durées.','Quatre mesures écrites puis enregistrées.','Chaque mesure totalise quatre temps ; les liaisons ne sont pas réattaquées ; la dernière mesure respire.',('Écrivez les durées avant de choisir une vitesse.','Une blanche suivie d’une demi-pause donne une fin simple.'),'Une solution : m.1 noire pointée + croche + deux noires sur La♭ ; m.2 une croche, une croche liée à une noire, puis deux noires sur La♭ ; m.3 noire, quatre doubles croches, deux croches, noire sur Sol ; m.4 blanche sur Sol puis demi-pause. Chaque mesure dure quatre temps.','sixteenths'),
    ]
    lessons=[
    sec('objectif','Objectif & résumé général','<p>Lire et jouer des rythmes variés : notes longues, subdivisions, valeurs pointées, silences, liaisons et triolets. Les treize exercices vont de la ronde à une phrase de plusieurs mesures. Le travail commence sur une seule hauteur confortable au ténor ; les notes cibles harmoniques arrivent à la fin.</p>'+call('Une difficulté à la fois','À chaque étape : lire les figures, compter les durées, frapper le rythme, écouter puis jouer. Commencez entre 40 et 60 à la pulsation et augmentez lorsque quatre mesures restent régulières trois fois de suite.')),
    sec('valeurs','Les valeurs de notes en 4/4',table(['Figure','Durée à la noire','Repère de lecture'],[['Ronde','4 temps','Tête ouverte, sans hampe.'],['Blanche','2 temps','Tête ouverte avec hampe.'],['Noire','1 temps','Tête pleine avec hampe.'],['Croche','½ temps','Une accroche ou une barre de groupe.'],['Double croche','¼ de temps','Deux accroches ou deux barres.']])+'<p>En 4/4, le dénominateur 4 désigne la noire comme unité du chiffrage. Une mesure contient quatre noires ou toute combinaison équivalente : une ronde, deux blanches, huit croches, seize doubles croches, ou un mélange.</p>'+call('Exemple concret','Blanche + noire + deux croches : 2 + 1 + ½ + ½ = 4 temps. Changer de figure ne change pas le tempo.')),
    sec('compter','Compter les subdivisions',table(['Division d’une noire','Comptage possible','Départs par temps'],[['Noire','1 · 2 · 3 · 4','1'],['Deux croches','1 et · 2 et · 3 et · 4 et','2'],['Quatre doubles croches','1-e-et-a · 2-e-et-a…','4'],['Triolet de croches','1-tri-let · 2-tri-let…','3']])+'<p>Le pied garde la pulsation. La voix découpe les subdivisions, y compris celles sur lesquelles aucune note ne commence. Choisissez un comptage et gardez-le stable.</p>'),
    sec('points','Le point ajoute la moitié',table(['Figure pointée','Calcul','Durée en 4/4'],[['Blanche pointée','2 + 1','3 temps'],['Noire pointée','1 + ½','1½ temps'],['Croche pointée','½ + ¼','¾ de temps']])+'<p>Le point allonge une note ; il ne demande pas une attaque supplémentaire. Une croche pointée suivie d’une double croche remplit un temps. Ne la confondez pas avec deux croches swing : le modèle pointé fait 3:1, le modèle swing d’étude 2:1.</p>'),
    sec('silences','Les silences ont les mêmes durées',table(['Silence','Valeur correspondante','Durée en 4/4'],[['Pause','Ronde','4 temps dans les exemples de ce cours'],['Demi-pause','Blanche','2 temps'],['Soupir','Noire','1 temps'],['Demi-soupir','Croche','½ temps'],['Quart de soupir','Double croche','¼ de temps']])+'<p>Une pause centrée peut aussi indiquer une mesure entière de silence dans d’autres chiffrages ; vérifiez le contexte. Au saxophone, interrompez le son pendant le silence et continuez à compter. Une respiration doit tenir dans la durée disponible.</p>'),
    sec('liaisons','Liées ou séparées : ce qui change','<p>Une liaison de prolongation unit deux notes de même hauteur. Leurs durées s’additionnent et la seconde tête n’est pas réattaquée. Une croche liée à une noire dure donc ½ + 1 = 1½ temps.</p><p>Sans liaison, les deux notes portent deux attaques. Une liaison peut traverser une barre de mesure : le son continue, le comptage passe à la nouvelle mesure.</p>'+call('Prolongation et phrasé','Une liaison de phrasé entre des hauteurs différentes indique une manière d’articuler une phrase. Elle ne transforme pas plusieurs hauteurs en une seule note tenue. Les courbes du lecteur indiquent ici des prolongations sur une hauteur identique.')),
    sec('ternaire','Triolets et mesures composées','<p>Un triolet de croches répartit trois notes égales sur un temps à la noire : chaque note dure ⅓ de temps. Un triolet de noires répartit trois notes sur deux temps : chaque note dure ⅔ de temps.</p><p>En 6/8, deux pulsations à la noire pointée regroupent naturellement trois croches chacune. Ces croches ne sont pas des triolets ajoutés : le regroupement vient du chiffrage. Le lecteur indique alors le tempo à la noire pointée, et non à la noire.</p>'+table(['Chiffrage','Pulsation retenue dans le lecteur','Pulsations par mesure'],[['4/4','Noire','4'],['3/4','Noire','3'],['6/8','Noire pointée','2']])) ,
    sec('ecouter','Atelier de lecture et d’écoute',tool.replace('<p class="mini" id="rhythm-description">',preferences('rhythm',True)+'<p class="mini" id="rhythm-description">')+'<p>Le clic marque les pulsations ; le son tenu suit les notes. Les silences interrompent le son et les liaisons le prolongent. En 6/8, les lumières montrent les deux pulsations composées. L’option « 2 et 4 » concerne uniquement le 4/4.</p>'),
    sec('progression','Une progression en treize étapes',table(['Étape','Lecture travaillée','Difficulté nouvelle'],[['1–3','Ronde, blanches, noires','Tenue puis partage de la mesure.'],['4','Croches et blanche','Subdiviser puis revenir à une tenue.'],['5','Blanche et noire pointées','Durées de 3 et 1½ temps.'],['6','Silences','Compter sans son.'],['7','Doubles croches et quart de soupir','Quatre subdivisions par temps.'],['8','Croche pointée + double croche','Rapport 3:1.'],['9','Notes liées ou séparées','Une attaque supprimée, une durée conservée.'],['10','Triolets de croches et de noires','Répartition ternaire.'],['11','Deux mesures liées','Traverser la barre sans réattaquer.'],['12','3/4 et 6/8','Changer le regroupement.'],['13','Phrase sur une cadence','Combiner rythme, harmonie et respiration.']])),
    sec('exercices','Exercices progressifs',''.join(exercises)),
    sec('revision','Erreurs fréquentes & fiche de révision','<ul><li>Accélérer quand apparaissent les croches ou les doubles croches : la pulsation garde la même vitesse.</li><li>Ajouter un temps après une valeur pointée : le point fait partie de la durée de la note.</li><li>Traiter un silence comme une attente libre.</li><li>Réattaquer la seconde note d’une liaison de prolongation.</li><li>Lire 6/8 comme six pulsations lentes alors que l’exercice demande deux pulsations composées.</li></ul>'+call('Avant de poursuivre','Nommer les figures, vérifier le total de chaque mesure, distinguer notes liées et séparées, puis jouer une phrase avec au moins un silence sans perdre le premier temps.')+'<p><b>Résumé final.</b> Les figures fixent les durées. Les points les prolongent. Les silences réservent une durée sans son. Les liaisons additionnent des durées sans nouvelle attaque. Le chiffrage organise les pulsations ; la phrase combine ces éléments sur une forme régulière.</p>')]
    page('rythme',lessons)
